import reviewModel from"../models/reviewModel.js";const addReview=async(req,res)=>{try{const{productId:productId,name:name,email:email,rating:rating,comment:comment}=req.body;if(await reviewModel.findOne({productId:productId,email:email}))return res.json({success:!1,message:"Ya has enviado una valoración para este producto"});const review=new reviewModel({productId:productId,name:name,email:email,rating:Number(rating),comment:comment,approved:!1});await review.save(),res.json({success:!0,message:"Valoración enviada. Pendiente de aprobación."})}catch(error){console.error(error),res.status(500).json({success:!1,message:error.message})}},getApprovedReviews=async(req,res)=>{try{const{productId:productId}=req.params,reviews=await reviewModel.find({productId:productId,approved:!0}).sort({createdAt:-1});res.json({success:!0,reviews:reviews})}catch(error){console.error(error),res.status(500).json({success:!1,message:error.message})}},getPendingReviews=async(req,res)=>{try{const reviews=await reviewModel.find({approved:!1}).populate("productId","name").sort({createdAt:-1});res.json({success:!0,reviews:reviews})}catch(error){console.error(error),res.status(500).json({success:!1,message:error.message})}},approveReview=async(req,res)=>{try{const{id:id}=req.params;await reviewModel.findByIdAndUpdate(id,{approved:!0}),res.json({success:!0,message:"Valoración aprobada"})}catch(error){console.error(error),res.status(500).json({success:!1,message:error.message})}},deleteReview=async(req,res)=>{try{const{id:id}=req.params;await reviewModel.findByIdAndDelete(id),res.json({success:!0,message:"Valoración eliminada"})}catch(error){console.error(error),res.status(500).json({success:!1,message:error.message})}};export{addReview,getApprovedReviews,getPendingReviews,approveReview,deleteReview};